"use client";

import type { ChangeEvent, ReactNode } from "react";
import type { AdminUserCreateInput, AdminUserMutationInput, AdminUserPreview } from "@/types/admin";
import type { UserRole } from "@/types/account";

export type AdminUserFormState = {
  role: UserRole;
  email: string;
  password: string;
  displayName: string;
  nombre: string;
  apellidos: string;
  headline: string;
  location: string;
  phone: string;
  companyName: string;
  companyDescription: string;
  plan: string;
  credits: string;
  verificationStatus: "" | "pending" | "verified" | "unverified";
  profileVisibility: "" | "public" | "private" | "recruiters_only";
};

const PLAN_OPTIONS: Record<UserRole, string[]> = {
  candidate: ["basic", "boosted", "pro"],
  company: ["basic", "pro", "business", "premium"],
  admin: ["premium"],
};

function joinClasses(...values: Array<string | false | null | undefined>) {
  return values.filter(Boolean).join(" ");
}

function normalizePlan(role: UserRole, plan?: string | null) {
  const options = PLAN_OPTIONS[role];
  return plan && options.includes(plan) ? plan : options[0];
}

function splitFullName(value: string) {
  const parts = value.trim().split(/\s+/).filter(Boolean);
  if (parts.length <= 1) {
    return { nombre: parts[0] ?? "", apellidos: "" };
  }
  return {
    nombre: parts.slice(0, 1).join(" "),
    apellidos: parts.slice(1).join(" "),
  };
}

function joinFullName(form: Pick<AdminUserFormState, "nombre" | "apellidos" | "companyName">) {
  return [form.nombre, form.apellidos].map((value) => value.trim()).filter(Boolean).join(" ") || form.companyName.trim();
}

function textInputClass(isDark: boolean) {
  return joinClasses(
    "w-full rounded-2xl border px-4 py-3 text-sm outline-none transition",
    isDark
      ? "border-white/10 bg-white/5 text-white placeholder:text-slate-500"
      : "border-slate-300 bg-white text-slate-900 placeholder:text-slate-400",
  );
}

function labelClass(isDark: boolean) {
  return joinClasses("text-xs font-semibold uppercase tracking-[0.18em]", isDark ? "text-slate-400" : "text-slate-500");
}

export function getPlanOptionsForRole(role: UserRole) {
  return PLAN_OPTIONS[role];
}

export function createEmptyAdminUserForm(role: UserRole = "candidate"): AdminUserFormState {
  return {
    role,
    email: "",
    password: "",
    displayName: "",
    nombre: "",
    apellidos: "",
    headline: role === "admin" ? "Administrador" : role === "company" ? "Employer Admin" : "Candidato",
    location: "",
    phone: "",
    companyName: "",
    companyDescription: "",
    plan: normalizePlan(role),
    credits: "",
    verificationStatus: role === "company" ? "pending" : "",
    profileVisibility: role === "candidate" ? "public" : "",
  };
}

export function createAdminUserFormFromUser(user: AdminUserPreview): AdminUserFormState {
  const splitName = splitFullName(user.nombre);
  return {
    role: user.role,
    email: user.email,
    password: "",
    displayName: user.displayName,
    nombre: splitName.nombre,
    apellidos: splitName.apellidos,
    headline: user.headline,
    location: user.location ?? "",
    phone: user.phone ?? "",
    companyName: user.companyName ?? "",
    companyDescription: user.companyDescription ?? "",
    plan: normalizePlan(user.role, user.plan),
    credits: String(user.credits),
    verificationStatus: user.verificationStatus ?? "",
    profileVisibility: user.profileVisibility ?? "",
  };
}

export function applyRoleToAdminUserForm(form: AdminUserFormState, role: UserRole): AdminUserFormState {
  return {
    ...form,
    role,
    plan: normalizePlan(role, form.plan),
    verificationStatus:
      role === "company"
        ? form.verificationStatus || "pending"
        : "",
    profileVisibility:
      role === "candidate"
        ? form.profileVisibility || "public"
        : "",
    companyName: role === "company" ? form.companyName : "",
    companyDescription: role === "company" ? form.companyDescription : "",
    headline:
      form.headline ||
      (role === "admin" ? "Administrador" : role === "company" ? "Employer Admin" : "Candidato"),
  };
}

function parseCredits(value: string) {
  const next = Number(value);
  return Number.isFinite(next) ? next : undefined;
}

export function getConfirmationName(user: AdminUserPreview) {
  return user.role === "company" ? user.companyName ?? user.nombre : user.nombre;
}

export function buildCreatePayload(form: AdminUserFormState): AdminUserCreateInput {
  const fullName = joinFullName(form);
  return {
    role: form.role,
    email: form.email.trim(),
    password: form.password,
    displayName: form.displayName.trim() || fullName,
    nombre: fullName,
    headline: form.headline.trim(),
    location: form.location.trim(),
    phone: form.phone.trim(),
    companyName: form.role === "company" ? form.companyName.trim() : undefined,
    companyDescription: form.role === "company" ? form.companyDescription.trim() : undefined,
    plan: form.plan,
    credits: parseCredits(form.credits),
    verificationStatus: form.role === "company" && form.verificationStatus ? form.verificationStatus : undefined,
    profileVisibility: form.role === "candidate" && form.profileVisibility ? form.profileVisibility : undefined,
  };
}

export function buildUpdatePayload(userId: string, form: AdminUserFormState): AdminUserMutationInput {
  const fullName = joinFullName(form);
  return {
    userId,
    role: form.role,
    email: form.email.trim(),
    password: form.password.trim() || undefined,
    displayName: form.displayName.trim(),
    nombre: fullName,
    headline: form.headline.trim(),
    location: form.location.trim(),
    phone: form.phone.trim(),
    companyName: form.role === "company" ? form.companyName.trim() : undefined,
    companyDescription: form.role === "company" ? form.companyDescription.trim() : undefined,
    plan: form.plan,
    credits: parseCredits(form.credits),
    verificationStatus: form.role === "company" && form.verificationStatus ? form.verificationStatus : undefined,
    profileVisibility: form.role === "candidate" && form.profileVisibility ? form.profileVisibility : undefined,
  };
}

function FormField({
  isDark,
  label,
  children,
}: {
  isDark: boolean;
  label: string;
  children: ReactNode;
}) {
  return (
    <label className="grid gap-2">
      <span className={labelClass(isDark)}>{label}</span>
      {children}
    </label>
  );
}

type FieldsProps = {
  isDark: boolean;
  form: AdminUserFormState;
  onChange: (next: AdminUserFormState) => void;
  includePasswordHint?: boolean;
};

export function AdminUserFormFields({
  isDark,
  form,
  onChange,
  includePasswordHint = false,
}: FieldsProps) {
  const handleTextField =
    (key: keyof AdminUserFormState) =>
    (event: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
      onChange({
        ...form,
        [key]: event.target.value,
      });
    };

  return (
    <div className="grid gap-4">
      <FormField isDark={isDark} label="Rol">
        <select
          value={form.role}
          onChange={(event) => onChange(applyRoleToAdminUserForm(form, event.target.value as UserRole))}
          className={textInputClass(isDark)}
        >
          <option value="candidate">candidate</option>
          <option value="company">company</option>
          <option value="admin">admin</option>
        </select>
      </FormField>

      <div className="grid gap-4 md:grid-cols-2">
        <FormField isDark={isDark} label="Nombre">
          <input value={form.nombre} onChange={handleTextField("nombre")} className={textInputClass(isDark)} />
        </FormField>
        <FormField isDark={isDark} label="Apellidos">
          <input value={form.apellidos} onChange={handleTextField("apellidos")} className={textInputClass(isDark)} />
        </FormField>
      </div>

      <FormField isDark={isDark} label="Display name">
        <input value={form.displayName} onChange={handleTextField("displayName")} className={textInputClass(isDark)} />
      </FormField>

      <FormField isDark={isDark} label="Headline">
        <input value={form.headline} onChange={handleTextField("headline")} className={textInputClass(isDark)} />
      </FormField>

      {form.role === "company" ? (
        <>
          <FormField isDark={isDark} label="Nombre de empresa">
            <input value={form.companyName} onChange={handleTextField("companyName")} className={textInputClass(isDark)} />
          </FormField>
          <FormField isDark={isDark} label="Descripcion de empresa">
            <textarea value={form.companyDescription} onChange={handleTextField("companyDescription")} className={joinClasses(textInputClass(isDark), "min-h-28")} />
          </FormField>
        </>
      ) : null}

      <div className="grid gap-4 md:grid-cols-2">
        <FormField isDark={isDark} label="Correo">
          <input type="email" value={form.email} onChange={handleTextField("email")} className={textInputClass(isDark)} />
        </FormField>
        <FormField isDark={isDark} label={includePasswordHint ? "Contrasena nueva o inicial" : "Contrasena"}>
          <input type="password" value={form.password} onChange={handleTextField("password")} className={textInputClass(isDark)} />
        </FormField>
      </div>

      <div className="grid gap-4 md:grid-cols-2">
        <FormField isDark={isDark} label="Ubicacion">
          <input value={form.location} onChange={handleTextField("location")} className={textInputClass(isDark)} />
        </FormField>
        <FormField isDark={isDark} label="Telefono">
          <input value={form.phone} onChange={handleTextField("phone")} className={textInputClass(isDark)} />
        </FormField>
      </div>

      <div className="grid gap-4 md:grid-cols-2">
        <FormField isDark={isDark} label="Plan">
          <select value={form.plan} onChange={handleTextField("plan")} className={textInputClass(isDark)}>
            {getPlanOptionsForRole(form.role).map((plan) => (
              <option key={plan} value={plan}>
                {plan}
              </option>
            ))}
          </select>
        </FormField>
        <FormField isDark={isDark} label="Creditos">
          <input type="number" min={0} value={form.credits} onChange={handleTextField("credits")} className={textInputClass(isDark)} />
        </FormField>
      </div>

      {form.role === "candidate" ? (
        <FormField isDark={isDark} label="Visibilidad">
          <select value={form.profileVisibility} onChange={handleTextField("profileVisibility")} className={textInputClass(isDark)}>
            <option value="public">public</option>
            <option value="recruiters_only">recruiters_only</option>
            <option value="private">private</option>
          </select>
        </FormField>
      ) : null}

      {form.role === "company" ? (
        <FormField isDark={isDark} label="Verificacion">
          <select value={form.verificationStatus} onChange={handleTextField("verificationStatus")} className={textInputClass(isDark)}>
            <option value="pending">pending</option>
            <option value="verified">verified</option>
            <option value="unverified">unverified</option>
          </select>
        </FormField>
      ) : null}
    </div>
  );
}
