"use client";

import Link from "next/link";
import { useState } from "react";
import { ArrowRight, Building2, UserPlus } from "lucide-react";
import { RoleRouteGuard } from "@/compartido/components/role/role-route-guard";
import { useAuthUser } from "@/compartido/hooks/use-auth-user";
import { useVacancyTheme } from "@/compartido/theme/use-vacancy-theme";
import { AdminDashboardShell } from "@/frontend/admin/components/system/admin-dashboard-shell";
import {
  AdminUserFormFields,
  buildCreatePayload,
  createEmptyAdminUserForm,
  type AdminUserFormState,
} from "@/frontend/admin/components/system/admin-user-form";
import { useAdminUsers } from "@/frontend/admin/hooks/use-admin-users";
import {
  AdminPrimaryButton,
  AdminSectionHeading,
  AdminSurface,
} from "@/frontend/admin/components/system/admin-dashboard-kit";

export default function AdminCreatePage() {
  const { isDark, toggleTheme } = useVacancyTheme();
  const { authUser } = useAuthUser();
  const enabled = authUser?.role === "admin";
  const { createAdminUser } = useAdminUsers(enabled);
  const [form, setForm] = useState<AdminUserFormState>(createEmptyAdminUserForm("candidate"));
  const [notice, setNotice] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  return (
    <RoleRouteGuard allowedRole="admin">
      <AdminDashboardShell isDark={isDark} onToggleTheme={toggleTheme} title="Crear/Create" description="Formulario completo para crear un nuevo usuario desde el panel de admin.">
        {notice ? (
          <div className={isDark ? "rounded-2xl border border-cyan-300/18 bg-cyan-300/8 px-4 py-3 text-sm text-cyan-100" : "rounded-2xl border border-sky-300 bg-sky-50 px-4 py-3 text-sm text-sky-700"}>
            {notice}
          </div>
        ) : null}

        <section className="grid gap-5 xl:grid-cols-[minmax(0,1.1fr)_22rem]">
          <AdminSurface isDark={isDark}>
            <AdminSectionHeading
              isDark={isDark}
              title="Nuevo usuario"
              description="Completa los datos requeridos. Si eliges rol empresa, el nombre de empresa y la verificación también quedan disponibles."
            />

            <div className="mt-6">
              <AdminUserFormFields isDark={isDark} form={form} onChange={setForm} />
            </div>

            <div className="mt-6 flex justify-end">
              <AdminPrimaryButton
                disabled={saving}
                onClick={async () => {
                  setSaving(true);
                  const result = await createAdminUser(buildCreatePayload(form));
                  setSaving(false);
                  setNotice(result === true ? "Usuario creado correctamente." : typeof result === "string" ? result : "No se pudo crear el usuario.");
                  if (result === true) {
                    setForm(createEmptyAdminUserForm(form.role));
                  }
                }}
              >
                <UserPlus className="h-4 w-4" />
                {saving ? "Creando..." : "Crear usuario"}
              </AdminPrimaryButton>
            </div>
          </AdminSurface>

          <div className="space-y-5">
            <AdminSurface isDark={isDark}>
              <AdminSectionHeading isDark={isDark} title="Atajos" description="Después de crear, puedes ir directo a editar o validar el registro." />
              <div className="mt-5 space-y-3">
                <Link
                  href="/admin/usuarios"
                  className={isDark ? "flex items-center justify-between rounded-2xl border border-white/8 bg-white/[0.04] px-4 py-3 text-sm text-slate-100" : "flex items-center justify-between rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-700"}
                >
                  <span className="inline-flex items-center gap-2">
                    <UserPlus className="h-4 w-4" />
                    Usuarios
                  </span>
                  <ArrowRight className="h-4 w-4" />
                </Link>
                <Link
                  href="/admin/vacantes"
                  className={isDark ? "flex items-center justify-between rounded-2xl border border-white/8 bg-white/[0.04] px-4 py-3 text-sm text-slate-100" : "flex items-center justify-between rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-700"}
                >
                  <span className="inline-flex items-center gap-2">
                    <Building2 className="h-4 w-4" />
                    Empresas
                  </span>
                  <ArrowRight className="h-4 w-4" />
                </Link>
              </div>
            </AdminSurface>
          </div>
        </section>
      </AdminDashboardShell>
    </RoleRouteGuard>
  );
}
